mapper.select:
select request_id from roam_presence_revoke_intent
where event_type='REVOKE' and ((state=0 and next_attempt_at <= now(6)) or (state=1 and lease_until <= now(6)))
order by id limit #{limit}

mapper.update:
update roam_presence_revoke_intent set state=case when attempt_count >= 3 then 3 else 0 end,
  next_attempt_at=date_add(now(6),interval (60*attempt_count) second),owner_token=null,lease_until=null
where request_id=#{requestId} and state=1 and owner_token=#{ownerToken}
